//! `dist/tokens.css` and an app's `design/theme.css`.

use design_system_model::spec::COLOR_TOKENS;
use design_system_model::{Combo, Resolved, Scheme};

pub const HEADER: &str =
    "Generated by design_system_cli render from design_system/tokens. Do not edit.";

/// How each colour token maps onto system colours when Windows high contrast
/// (`forced-colors: active`) is on, so the system's colours win.
fn forced_color(token: &str) -> &'static str {
    match token {
        "bg" | "surface" | "surface-raised" => "Canvas",
        "text" | "text-muted" | "border-strong" => "CanvasText",
        "border" => "GrayText",
        "link" => "LinkText",
        "accent" | "accent-hover" | "focus" => "Highlight",
        "on-accent" => "HighlightText",
        t if t.starts_with("on-") => "Canvas",
        _ => "CanvasText",
    }
}

fn find(all: &[Resolved], scheme: Scheme, accessible: bool) -> Option<&Resolved> {
    all.iter().find(|r| r.combo == Combo { scheme, accessible })
}

fn colors(out: &mut String, r: &Resolved, unless_same_as: Option<&Resolved>) {
    for (k, v) in &r.colors {
        if unless_same_as.and_then(|b| b.color(k)) == Some(*v) {
            continue;
        }
        out.push_str(&format!("  --ds-color-{k}: {v};\n"));
    }
}

fn others(out: &mut String, r: &Resolved, unless_same_as: Option<&Resolved>) {
    for (k, v) in &r.tokens {
        if unless_same_as.and_then(|b| b.token(k)) == Some(v.as_str()) {
            continue;
        }
        out.push_str(&format!("  --ds-{k}: {v};\n"));
    }
}

fn rule(out: &mut String, media: Option<&str>, selector: &str, body: &str) {
    match media {
        Some(m) => {
            out.push_str(&format!("@media {m} {{\n  {selector} {{\n"));
            for line in body.lines() {
                out.push_str(&format!("  {line}\n"));
            }
            out.push_str("  }\n}\n");
        }
        None => out.push_str(&format!("{selector} {{\n{body}}}\n")),
    }
}

const DARK: &str = "(prefers-color-scheme: dark)";
const MORE: &str = "(prefers-contrast: more)";

/// The rules for one theme: every combination it has, keyed on the `<html>`
/// attributes, with media query defaults for pages that haven't chosen.
pub fn theme_css(name: &str, all: &[Resolved]) -> String {
    let t = format!("[data-theme=\"{name}\"]");
    let mut out = String::new();
    let Some(light) = find(all, Scheme::Light, false) else {
        return out;
    };

    let mut body = String::from("  color-scheme: light;\n");
    others(&mut body, light, None);
    colors(&mut body, light, None);
    rule(&mut out, None, &t, &body);

    if let Some(dark) = find(all, Scheme::Dark, false) {
        let mut body = String::from("  color-scheme: dark;\n");
        colors(&mut body, dark, Some(light));
        rule(&mut out, None, &format!("{t}[data-scheme=\"dark\"]"), &body);
        rule(
            &mut out,
            Some(DARK),
            &format!("{t}:not([data-scheme=\"light\"])"),
            &body,
        );
    }

    if let Some(a_light) = find(all, Scheme::Light, true) {
        let mut body = String::new();
        others(&mut body, a_light, Some(light));
        colors(&mut body, a_light, Some(light));
        rule(&mut out, None, &format!("{t}[data-a11y=\"on\"]"), &body);
        rule(
            &mut out,
            Some(MORE),
            &format!("{t}:not([data-a11y=\"off\"])"),
            &body,
        );
    }

    if let Some(a_dark) = find(all, Scheme::Dark, true) {
        // Every colour: this block has to beat both the dark and the
        // accessible light blocks, which also match.
        let mut body = String::from("  color-scheme: dark;\n");
        colors(&mut body, a_dark, None);
        let (on, off_light, dark, off_a11y) = (
            "[data-a11y=\"on\"]",
            ":not([data-scheme=\"light\"])",
            "[data-scheme=\"dark\"]",
            ":not([data-a11y=\"off\"])",
        );
        rule(&mut out, None, &format!("{t}{dark}{on}"), &body);
        rule(&mut out, Some(DARK), &format!("{t}{on}{off_light}"), &body);
        rule(&mut out, Some(MORE), &format!("{t}{dark}{off_a11y}"), &body);
        rule(
            &mut out,
            Some(&format!("{DARK} and {MORE}")),
            &format!("{t}{off_light}{off_a11y}"),
            &body,
        );
    }
    out
}

/// Rules that apply whatever the theme: reduced motion and forced colours.
pub fn shared_css() -> String {
    let mut out = String::new();
    rule(
        &mut out,
        Some("(prefers-reduced-motion: reduce)"),
        ":root[data-theme]",
        "  --ds-motion-fast: 0ms;\n  --ds-motion-slow: 0ms;\n",
    );
    let mut body = String::new();
    for k in COLOR_TOKENS {
        body.push_str(&format!(
            "  --ds-color-{k}: {} !important;\n",
            forced_color(k)
        ));
    }
    body.push_str("  --ds-shadow-1: none !important;\n  --ds-shadow-2: none !important;\n  --ds-shadow-3: none !important;\n");
    rule(
        &mut out,
        Some("(forced-colors: active)"),
        ":root[data-theme]",
        &body,
    );
    out
}

/// `dist/tokens.css`: every standard theme.
pub fn tokens_css(themes: &[(String, Vec<Resolved>)]) -> String {
    let mut out = format!(
        "/* {HEADER}\n *\n * Set data-theme on <html> to one of: {}.\n * data-scheme=\"light\" or \"dark\" and data-a11y=\"on\" or \"off\" are optional;\n * without them the page follows prefers-color-scheme and prefers-contrast.\n */\n\n",
        themes
            .iter()
            .map(|(n, _)| n.as_str())
            .collect::<Vec<_>>()
            .join(", ")
    );
    for (name, all) in themes {
        out.push_str(&format!("/* {name} */\n"));
        out.push_str(&theme_css(name, all));
        out.push('\n');
    }
    out.push_str("/* every theme */\n");
    out.push_str(&shared_css());
    out
}

/// `<app>/design/theme.css`: one custom theme, loaded after `tokens.css`.
pub fn app_css(app: &str, name: &str, extends: &str, all: &[Resolved]) -> String {
    format!(
        "/* {HEADER}\n * Source: {app}/design/theme.toml. Load after design_system/dist/tokens.css.\n * Custom theme {name:?}, extending {extends:?}: set data-theme=\"{name}\" on <html>.\n */\n\n{}",
        theme_css(name, all)
    )
}
